def lib(u):
    import itertools
    D = {'1': np.ones(len(u))}
    d = u.shape[1]
    for j in range(d):
        x = u[:, j]
        for (n, f) in [('x', lambda x: x), ('q', lambda x: x * x), ('cube', lambda x: x ** 3), ('tanh', np.tanh), ('sin', np.sin), ('cos', np.cos), ('atan', np.arctan), ('soft', lambda x: x / (1 + x * x)), ('sat', lambda x: x / np.sqrt(1 + x * x)), ('abs', np.abs)]:
            D[f'{n}{j}'] = f(x)
    for (j, k) in itertools.combinations(range(d), 2):
        (x, y) = (u[:, j], u[:, k])
        D[f'prod{j}{k}'] = x * y
        for (a, z) in [('+', x + y), ('-', x - y)]:
            for (n, f) in [('tanh', np.tanh), ('sin', np.sin), ('cos', np.cos)]:
                D[f'{n}{j}{a}{k}'] = f(z)
    return D

def _coordinates(x, maps):
    (offset, gain, operator) = maps
    return _affine((x - offset) / gain) @ operator

def _trajectory(c, query, traj, times, intercept=True):
    from scipy.optimize import least_squares
    (design, new_design) = (_affine(c), _affine(query)) if intercept else (c, query)
    beta = np.linalg.lstsq(design, traj, rcond=None)[0]
    fitted = design @ beta
    scale = max(float(np.max(np.abs(times))), np.finfo(float).tiny)
    t = times / scale

    def basis(log_rates):
        return -np.expm1(-np.exp(log_rates[:, None]) * t)

    def residual(log_rates):
        modes = basis(log_rates)
        return (fitted @ np.linalg.pinv(modes) @ modes - fitted).ravel()
    log_rates = least_squares(residual, np.log([0.6, 2.7]), bounds=(np.log([0.03, 0.25]), np.log([4.0, 20.0])), max_nfev=100).x
    modes = basis(log_rates)
    return new_design @ (beta @ np.linalg.pinv(modes)) @ modes
